def tau(n):
    """Calculates the number of positive divisors of n."""
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def d(n):
    """Calculates the number of positive divisors of n other than 1 and itself."""
    if n < 2:
        return -1 # Or handle as an error, but since n starts from 2, this won't happen for d(n)
    return tau(n) - 2

